    // Mu A[4]: aCrystalLaneB[21] + aEarthLaneA[58].
    KEY_FOLD_BLOCK(aCrystalLaneB, 21U, 405U, aEarthLaneA, 58U, 495U, aMuLaneA, 4U);

    // Mu A[5]: aEarthLaneC[40] + aEarthLaneD[59].
    KEY_FOLD_BLOCK(aEarthLaneC, 40U, 480U, aEarthLaneD, 59U, 113U, aMuLaneA, 5U);

    // Mu A[6]: aEarthLaneC[52] + aEarthLaneA[50].
